-- Seed: 002_seed_borough_catalog_large.sql
-- Purpose:
--   Seed catalog-service with 10 mnemonic categories, 200 products, and 400 variants.
--
-- ID strategy:
--   category_id -> mnemonic and human-searchable, e.g. cat_lang_go
--   product_id  -> opaque external ID, e.g. prod_<26 Crockford Base32 chars>
--   variant_id  -> opaque external ID, e.g. var_<26 Crockford Base32 chars>
--
-- Notes:
--   - Seed data is for local development and portfolio demos.
--   - It is not part of the migration history.
--   - It assumes the catalog schema created by db/catalog/migrations/000001_create_catalog_schema.up.sql.
--   - It keeps most products and variants active, with a small number inactive/draft for include_inactive testing.
--
-- Recommended local usage:
--   make local-db-fresh-catalog
--   mysql -h 127.0.0.1 -P 3306 -ubfstore_catalog -pbfstore_catalog_password bfstore_catalog < db/catalog/seeds/002_seed_borough_catalog_large.sql

USE bfstore_catalog;

SET @old_foreign_key_checks = @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 1;

